[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0A0A0A;
      --surface: #111111;
      --surface-2: #1A1A1A;
      --border: #222222;
      --border-light: #2E2E2E;
      --text: #FFFFFF;
      --text-muted: #888888;
      --text-dim: #555555;
      --accent: #3B7BFF;
      --accent-hover: #5590FF;
      --amber: #F5A623;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      background: var(--bg);
      color: var(--text);
      font-family: var(--font);
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ─── SCROLLBAR ──────────────────────────────── */
    ::-webkit-scrollbar { width: 4px; height: 4px; }
    ::-webkit-scrollbar-track { background: var(--bg); }
    ::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 2px; }

    /* ─── TYPOGRAPHY ─────────────────────────────── */
    h1, h2, h3, h4, h5 { font-weight: 700; line-height: 1.1; letter-spacing: -0.02em; }

    /* ─── NAV ────────────────────────────────────── */
    .nav {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 100;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 40px;
      height: 68px;
      background: rgba(10,10,10,0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid rgba(255,255,255,0.05);
      transition: background 0.3s;
    }

    .nav-logo {
      font-size: 18px;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--text);
      text-decoration: none;
      flex-shrink: 0;
    }
    .nav-logo span { color: var(--accent); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }
    .nav-links a {
      font-size: 13px;
      font-weight: 500;
      color: var(--text-muted);
      text-decoration: none;
      letter-spacing: 0.02em;
      transition: color 0.2s;
    }
    .nav-links a:hover { color: var(--text); }
    .nav-links .nav-cta {
      background: var(--accent);
      color: #fff;
      padding: 8px 18px;
      border-radius: 4px;
      font-size: 13px;
      font-weight: 600;
      transition: background 0.2s, transform 0.15s;
    }
    .nav-links .nav-cta:hover { background: var(--accent-hover); color: #fff; transform: translateY(-1px); }

    .nav-right {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    /* Language selector */
    .lang-selector {
      position: relative;
    }
    .lang-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      background: none;
      border: 1px solid var(--border-light);
      color: var(--text-muted);
      font-family: var(--font);
      font-size: 12px;
      font-weight: 500;
      padding: 6px 10px;
      border-radius: 4px;
      cursor: pointer;
      transition: border-color 0.2s, color 0.2s;
      letter-spacing: 0.02em;
    }
    .lang-btn:hover { border-color: var(--text-muted); color: var(--text); }
    .lang-btn i { font-size: 14px; transition: transform 0.2s; }
    .lang-btn.open i.ri-arrow-down-s-line { transform: rotate(180deg); }

    .lang-dropdown {
      display: none;
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--surface-2);
      border: 1px solid var(--border-light);
      border-radius: 6px;
      overflow: hidden;
      min-width: 140px;
      box-shadow: 0 16px 40px rgba(0,0,0,0.6);
    }
    .lang-dropdown.open { display: block; }
    .lang-dropdown a {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 14px;
      font-size: 13px;
      color: var(--text-muted);
      text-decoration: none;
      transition: background 0.15s, color 0.15s;
    }
    .lang-dropdown a:hover { background: var(--surface); color: var(--text); }
    .lang-dropdown a.active { color: var(--text); font-weight: 600; }

    /* Hamburger */
    .hamburger {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      color: var(--text);
      font-size: 24px;
      padding: 4px;
    }

    .mobile-menu {
      display: none;
      position: fixed;
      top: 68px; left: 0; right: 0; bottom: 0;
      background: var(--bg);
      z-index: 99;
      flex-direction: column;
      padding: 32px 24px;
      gap: 8px;
    }
    .mobile-menu.open { display: flex; }
    .mobile-menu a {
      font-size: 20px;
      font-weight: 600;
      color: var(--text);
      text-decoration: none;
      padding: 14px 0;
      border-bottom: 1px solid var(--border);
      transition: color 0.2s;
    }
    .mobile-menu a:hover { color: var(--accent); }

    /* ─── HERO ───────────────────────────────────── */
    .hero {
      position: relative;
      height: 100vh;
      min-height: 600px;
      overflow: hidden;
    }

    .hero-slides {
      position: relative;
      width: 100%;
      height: 100%;
    }

    .hero-slide {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: flex-end;
      padding: 0 80px 100px;
      opacity: 0;
      transition: opacity 0.8s ease;
      pointer-events: none;
    }
    .hero-slide.active {
      opacity: 1;
      pointer-events: all;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
      transition: transform 8s ease;
    }
    .hero-slide.active .hero-bg { transform: scale(1.04); }

    .hero-bg-1 { background: linear-gradient(135deg, #0a0a1a 0%, #0f1a3a 40%, #1a0a2e 100%); }
    .hero-bg-2 { background: linear-gradient(135deg, #0a1a0f 0%, #0f3a1a 40%, #1a2e0a 100%); }
    .hero-bg-3 { background: linear-gradient(135deg, #1a0a0a 0%, #3a0f0f 40%, #2e1a0a 100%); }
    .hero-bg-4 { background: linear-gradient(135deg, #0a0a1a 0%, #1a0a3a 40%, #0f0f2e 100%); }
    .hero-bg-5 { background: linear-gradient(135deg, #0a1a1a 0%, #0a3a2e 40%, #1a2e1a 100%); }

    .hero-bg::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(10,10,10,0.9) 0%, rgba(10,10,10,0.3) 50%, rgba(10,10,10,0.1) 100%);
    }

    /* Decorative grid overlay */
    .hero-bg::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
      background-size: 80px 80px;
      z-index: 1;
    }

    .hero-content {
      position: relative;
      z-index: 2;
      max-width: 720px;
    }

    .hero-tag {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--accent);
      background: rgba(59,123,255,0.12);
      border: 1px solid rgba(59,123,255,0.25);
      padding: 5px 12px;
      border-radius: 20px;
      margin-bottom: 20px;
    }

    .hero-title {
      font-size: clamp(36px, 5.5vw, 72px);
      font-weight: 800;
      line-height: 1.05;
      letter-spacing: -0.03em;
      color: #fff;
      margin-bottom: 20px;
    }

    .hero-body {
      font-size: 17px;
      line-height: 1.65;
      color: rgba(255,255,255,0.7);
      margin-bottom: 32px;
      max-width: 560px;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: #fff;
      color: #000;
      font-size: 14px;
      font-weight: 700;
      padding: 14px 28px;
      border-radius: 4px;
      text-decoration: none;
      letter-spacing: 0.01em;
      transition: background 0.2s, transform 0.15s;
    }
    .hero-cta:hover { background: rgba(255,255,255,0.88); transform: translateY(-2px); }
    .hero-cta i { font-size: 16px; }

    /* Hero nav controls */
    .hero-controls {
      position: absolute;
      bottom: 40px;
      right: 80px;
      z-index: 10;
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .hero-dots {
      display: flex;
      gap: 8px;
      align-items: center;
    }
    .hero-dot {
      width: 24px;
      height: 3px;
      background: rgba(255,255,255,0.25);
      border-radius: 2px;
      cursor: pointer;
      transition: background 0.3s, width 0.3s;
      border: none;
    }
    .hero-dot.active {
      background: #fff;
      width: 40px;
    }

    .hero-arrows {
      display: flex;
      gap: 8px;
    }
    .hero-arrow {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      border: 1px solid rgba(255,255,255,0.2);
      background: rgba(255,255,255,0.06);
      color: #fff;
      font-size: 18px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s, border-color 0.2s;
      backdrop-filter: blur(8px);
    }
    .hero-arrow:hover { background: rgba(255,255,255,0.15); border-color: rgba(255,255,255,0.4); }

    /* ─── SECTIONS COMMON ────────────────────────── */
    section { padding: 100px 80px; }

    .section-label {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(28px, 3.5vw, 48px);
      font-weight: 700;
      letter-spacing: -0.025em;
      margin-bottom: 16px;
    }

    .section-subtitle {
      font-size: 16px;
      line-height: 1.65;
      color: var(--text-muted);
      max-width: 540px;
    }

    .section-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 60px;
      gap: 40px;
    }
    .section-header-left { flex: 1; }

    /* ─── TEAM CAROUSEL ──────────────────────────── */
    .team-section {
      background: var(--surface);
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
    }

    .region-tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 48px;
      border-bottom: 1px solid var(--border);
      padding-bottom: 0;
    }

    .region-tab {
      background: none;
      border: none;
      color: var(--text-dim);
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      padding: 12px 20px;
      cursor: pointer;
      position: relative;
      letter-spacing: 0.01em;
      transition: color 0.2s;
      border-bottom: 2px solid transparent;
      margin-bottom: -1px;
    }
    .region-tab:hover { color: var(--text-muted); }
    .region-tab.active {
      color: var(--text);
      border-bottom-color: var(--accent);
    }

    .team-region { display: none; }
    .team-region.active { display: block; }

    .team-carousel-wrap {
      position: relative;
      overflow: hidden;
    }

    .team-cards {
      display: flex;
      gap: 24px;
      transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
    }

    .team-card {
      flex: 0 0 calc(33.333% - 16px);
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      transition: border-color 0.2s, transform 0.2s;
    }
    .team-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
    }

    .team-card-img {
      width: 100%;
      height: 260px;
      object-fit: cover;
      display: block;
      background: var(--surface);
    }

    .team-photo-placeholder {
      width: 100%;
      height: 260px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 64px;
      color: var(--text-dim);
      background: linear-gradient(135deg, var(--surface-2), var(--border));
    }

    .team-card-body {
      padding: 24px;
    }

    .team-card-quote {
      font-size: 14px;
      line-height: 1.7;
      color: var(--text-muted);
      font-style: italic;
      margin-bottom: 20px;
      border-left: 2px solid var(--accent);
      padding-left: 16px;
    }

    .team-card-name {
      font-size: 16px;
      font-weight: 700;
      color: var(--text);
      margin-bottom: 4px;
    }

    .team-card-title {
      font-size: 13px;
      color: var(--text-dim);
      margin-bottom: 16px;
    }

    .team-card-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
      font-weight: 600;
      color: var(--accent);
      text-decoration: none;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      transition: color 0.2s, gap 0.2s;
    }
    .team-card-cta:hover { color: var(--accent-hover); gap: 10px; }

    .team-carousel-nav {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 32px;
    }

    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--border-light);
      background: none;
      color: var(--text-muted);
      font-size: 18px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s, color 0.2s, border-color 0.2s;
    }
    .carousel-btn:hover {
      background: var(--surface-2);
      color: var(--text);
      border-color: var(--text-dim);
    }
    .carousel-btn:disabled { opacity: 0.3; cursor: default; }

    /* ─── WORK SHOWCASE ──────────────────────────── */
    .work-section { background: var(--bg); }

    .work-scroll-wrap {
      overflow: hidden;
      cursor: grab;
      user-select: none;
    }
    .work-scroll-wrap:active { cursor: grabbing; }

    .work-cards {
      display: flex;
      gap: 24px;
      transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
    }

    .work-card {
      flex: 0 0 420px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      transition: border-color 0.25s, transform 0.25s;
    }
    .work-card:hover {
      border-color: var(--border-light);
      transform: translateY(-6px);
    }

    .work-card-img {
      width: 100%;
      height: 240px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
      background: linear-gradient(135deg, var(--surface-2), #1e1e1e);
      position: relative;
      overflow: hidden;
    }
    .work-card-img::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.5) 0%, transparent 60%);
    }

    .work-card-client {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 8px;
    }

    .work-card-title {
      font-size: 18px;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 12px;
      letter-spacing: -0.01em;
    }

    .work-card-quote {
      font-size: 13px;
      line-height: 1.65;
      color: var(--text-muted);
      font-style: italic;
      margin-bottom: 16px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .work-card-attribution {
      font-size: 12px;
      color: var(--text-dim);
      font-weight: 500;
    }

    .work-card-body { padding: 24px; }

    .work-carousel-nav {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 32px;
    }

    /* ─── CTA BANNER ─────────────────────────────── */
    .cta-banner {
      background: linear-gradient(135deg, var(--accent) 0%, #1e50d4 100%);
      padding: 80px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 60px;
    }

    .cta-banner-text h2 {
      font-size: clamp(28px, 3.5vw, 44px);
      font-weight: 800;
      color: #fff;
      margin-bottom: 12px;
      letter-spacing: -0.025em;
    }

    .cta-banner-text p {
      font-size: 16px;
      line-height: 1.65;
      color: rgba(255,255,255,0.8);
      max-width: 520px;
    }

    .cta-banner-btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: #fff;
      color: var(--accent);
      font-size: 15px;
      font-weight: 700;
      padding: 16px 36px;
      border-radius: 4px;
      text-decoration: none;
      white-space: nowrap;
      transition: transform 0.15s, box-shadow 0.15s;
    }
    .cta-banner-btn:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.3); }

    /* ─── HOW WE WORK ────────────────────────────── */
    .how-section {
      background: var(--surface);
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .how-title {
      font-size: clamp(32px, 4vw, 56px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.05;
      margin-bottom: 24px;
    }

    .how-body {
      font-size: 16px;
      line-height: 1.75;
      color: var(--text-muted);
      margin-bottom: 32px;
    }

    .btn-outline {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      border: 1px solid var(--border-light);
      color: var(--text);
      font-size: 14px;
      font-weight: 600;
      padding: 12px 24px;
      border-radius: 4px;
      text-decoration: none;
      transition: background 0.2s, border-color 0.2s, transform 0.15s;
    }
    .btn-outline:hover { background: var(--surface-2); border-color: var(--text-dim); transform: translateY(-1px); }

    .how-visual {
      position: relative;
      height: 400px;
      border-radius: 8px;
      overflow: hidden;
      background: linear-gradient(135deg, #0f1a3a, #1a0f2e);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 80px;
      border: 1px solid var(--border);
    }

    .how-visual::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(59,123,255,0.08) 1px, transparent 1px),
        linear-gradient(90deg, rgba(59,123,255,0.08) 1px, transparent 1px);
      background-size: 40px 40px;
    }

    /* ─── LATEST INSIGHTS ────────────────────────── */
    .insights-section { background: var(--bg); }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .insight-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      text-decoration: none;
      color: var(--text);
      display: flex;
      flex-direction: column;
      transition: border-color 0.2s, transform 0.2s;
    }
    .insight-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
    }

    .insight-card-img {
      width: 100%;
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 36px;
      background: linear-gradient(135deg, var(--surface-2), #1e1e1e);
    }

    .insight-card-body {
      padding: 20px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }

    .insight-type {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 10px;
    }

    .insight-title {
      font-size: 15px;
      font-weight: 600;
      line-height: 1.45;
      margin-bottom: 16px;
      flex: 1;
      letter-spacing: -0.01em;
    }

    .insight-cta {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      font-size: 12px;
      font-weight: 600;
      color: var(--accent);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      transition: gap 0.2s;
    }
    .insight-card:hover .insight-cta { gap: 9px; }

    /* ─── PRINCIPLES ─────────────────────────────── */
    .principles-section {
      background: var(--surface);
      border-top: 1px solid var(--border);
    }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      margin-top: 60px;
    }

    .principle {
      border-top: 2px solid var(--border-light);
      padding-top: 28px;
      transition: border-color 0.2s;
    }
    .principle:hover { border-top-color: var(--accent); }

    .principle-num {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.12em;
      color: var(--text-dim);
      margin-bottom: 16px;
      text-transform: uppercase;
    }

    .principle-title {
      font-size: 18px;
      font-weight: 700;
      letter-spacing: -0.01em;
      margin-bottom: 12px;
    }

    .principle-body {
      font-size: 14px;
      line-height: 1.75;
      color: var(--text-muted);
    }

    /* ─── FOOTER ─────────────────────────────────── */
    .footer {
      background: var(--bg);
      border-top: 1px solid var(--border);
      padding: 80px 80px 40px;
    }

    .footer-top {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      margin-bottom: 60px;
      padding-bottom: 60px;
      border-bottom: 1px solid var(--border);
    }

    .footer-cta-block h3 {
      font-size: 22px;
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 12px;
      line-height: 1.3;
    }

    .footer-cta-block p {
      font-size: 14px;
      color: var(--text-muted);
      line-height: 1.65;
      margin-bottom: 20px;
    }

    .footer-cta-block a {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 13px;
      font-weight: 700;
      color: var(--accent);
      text-decoration: none;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      transition: color 0.2s, gap 0.2s;
    }
    .footer-cta-block a:hover { color: var(--accent-hover); gap: 10px; }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 20px;
    }

    .footer-nav {
      display: flex;
      gap: 24px;
      flex-wrap: wrap;
    }
    .footer-nav a {
      font-size: 13px;
      color: var(--text-dim);
      text-decoration: none;
      transition: color 0.2s;
    }
    .footer-nav a:hover { color: var(--text-muted); }

    .footer-legal {
      font-size: 12px;
      color: var(--text-dim);
      display: flex;
      align-items: center;
      gap: 20px;
      flex-wrap: wrap;
    }
    .footer-legal a {
      color: var(--text-dim);
      text-decoration: none;
      transition: color 0.2s;
    }
    .footer-legal a:hover { color: var(--text-muted); }

    /* ─── COOKIE BANNER ──────────────────────────── */
    .cookie-banner {
      position: fixed;
      bottom: 24px;
      left: 24px;
      right: 24px;
      max-width: 680px;
      z-index: 200;
      background: var(--surface-2);
      border: 1px solid var(--border-light);
      border-radius: 10px;
      padding: 24px 28px;
      display: flex;
      align-items: flex-start;
      gap: 20px;
      box-shadow: 0 24px 60px rgba(0,0,0,0.7);
      animation: slideUp 0.4s ease forwards;
    }

    @keyframes slideUp {
      from { transform: translateY(24px); opacity: 0; }
      to { transform: translateY(0); opacity: 1; }
    }

    .cookie-banner.hidden { display: none; }

    .cookie-banner-icon {
      font-size: 28px;
      flex-shrink: 0;
      margin-top: 2px;
    }

    .cookie-banner-content { flex: 1; }

    .cookie-banner-content h4 {
      font-size: 15px;
      font-weight: 700;
      margin-bottom: 6px;
    }

    .cookie-banner-content p {
      font-size: 13px;
      color: var(--text-muted);
      line-height: 1.6;
      margin-bottom: 16px;
    }

    .cookie-banner-actions {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    .cookie-btn {
      font-family: var(--font);
      font-size: 13px;
      font-weight: 600;
      padding: 8px 18px;
      border-radius: 4px;
      cursor: pointer;
      border: none;
      transition: all 0.2s;
    }
    .cookie-btn-accept {
      background: var(--accent);
      color: #fff;
    }
    .cookie-btn-accept:hover { background: var(--accent-hover); }
    .cookie-btn-manage {
      background: none;
      border: 1px solid var(--border-light);
      color: var(--text-muted);
    }
    .cookie-btn-manage:hover { border-color: var(--text-dim); color: var(--text); }
    .cookie-btn-decline {
      background: none;
      color: var(--text-dim);
      border: none;
      padding: 8px 12px;
    }
    .cookie-btn-decline:hover { color: var(--text-muted); }

    .cookie-close {
      background: none;
      border: none;
      color: var(--text-dim);
      font-size: 20px;
      cursor: pointer;
      flex-shrink: 0;
      padding: 2px;
      transition: color 0.2s;
    }
    .cookie-close:hover { color: var(--text); }

    /* ─── RESPONSIVE ─────────────────────────────── */
    @media (max-width: 1200px) {
      .insights-grid { grid-template-columns: repeat(3, 1fr); }
      .principles-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 1024px) {
      section { padding: 80px 40px; }
      .hero-slide { padding: 0 40px 80px; }
      .hero-controls { right: 40px; }
      .work-card { flex: 0 0 340px; }
      .team-card { flex: 0 0 calc(50% - 12px); }
      .how-section { grid-template-columns: 1fr; gap: 40px; }
      .how-visual { height: 300px; }
      .footer { padding: 60px 40px 32px; }
      .footer-top { grid-template-columns: 1fr; gap: 40px; }
      .cta-banner { flex-direction: column; padding: 60px 40px; gap: 32px; }
    }

    @media (max-width: 768px) {
      .nav { padding: 0 20px; }
      .nav-links { display: none; }
      .hamburger { display: flex; }

      section { padding: 60px 20px; }
      .hero-slide { padding: 0 20px 80px; }
      .hero-controls { right: 20px; bottom: 30px; }
      .hero-arrows { display: none; }

      .section-header { flex-direction: column; align-items: flex-start; gap: 16px; }
      .section-header .btn-outline { display: none; }

      .team-card { flex: 0 0 calc(100% - 0px); }
      .work-card { flex: 0 0 280px; }
      .insights-grid { grid-template-columns: 1fr 1fr; }
      .principles-grid { grid-template-columns: 1fr; gap: 28px; }
      .cta-banner { padding: 48px 20px; }
      .footer { padding: 48px 20px 28px; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }

      .cookie-banner { left: 16px; right: 16px; bottom: 16px; }
    }

    @media (max-width: 480px) {
      .insights-grid { grid-template-columns: 1fr; }
      .region-tab { font-size: 12px; padding: 10px 14px; }
    }

    /* ─── UTILITIES ──────────────────────────────── */
    .visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
  </style>
